-- BENCHMARK SEED: 512 dedicated load-test users.
-- Password: 'admin' (same legacy SHA256+salt as dev_admin_user.sql)
-- PasswordHasher::verify accepts the legacy hash; AuthService then
-- transparently rehashes to PBKDF2 on first successful login
-- (AuthService.cc:94-122). The benchmark setup warmup step logs each
-- user in once to complete that rehash BEFORE timed runs, so the
-- PBKDF2 cost lands in warmup, not in measured throughput.
-- DO NOT use these credentials in production!

-- 512 users, batch INSERT ... ON CONFLICT DO NOTHING.
ON CONFLICT (username) DO NOTHING;

-- Assign 'user' role to all 512 bench users.
SELECT u.id, r.id
FROM users u, roles r
WHERE u.username LIKE 'bench\_user\_%' AND r.name = 'user'
ON CONFLICT DO NOTHING;

-- Create subject mapping for all 512 bench users (provider 'local').
SELECT u.id::text, u.id, 'local'
FROM users u
WHERE u.username LIKE 'bench\_user\_%'
ON CONFLICT (provider, subject) DO NOTHING;
